 async function reviewCrewTripRequest(request:any,decision:'Approved'|'Declined'){
  if(crewRequestBusy)return;
  let decisionNote='',replacementCrewId='';
  if(decision==='Declined'){decisionNote=prompt('Optional note to the crew member:','')||'';}
  if(decision==='Approved'){
   replacementCrewId=crewReplacements[request.id]||'';
   if(!replacementCrewId){setMessage('Assign a replacement crew member before approving '+request.crewName+'\'s request.');return;}
   const replacement=crewPool.find((member:any)=>member.id===replacementCrewId);
   if(!replacement){setMessage('Choose a valid replacement crew member.');return;}
   if(!confirm('Approve '+request.crewName+'\'s request to leave '+request.tripNames.join(' + ')+' on '+displayDate(request.date)+' at '+request.time+'?\n\n'+replacement.name+' will be assigned as the replacement immediately.'))return;
  }
  setCrewRequestBusy(request.id);setMessage('');
  try{
   const r=await fetch('/api/crew-trip-requests',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:request.id,decision,decisionNote,replacementCrewId})}),d:any=await r.json();
   if(!r.ok)throw Error(d.error||'Could not review crew request.');
   if(decision==='Approved'){
    setMessage(request.crewName+'\'s request approved. '+(d.replacementCrewName||'Replacement crew')+' has been assigned to the trip.');
    setCrewReplacements(current=>{const next={...current};delete next[request.id];return next;});
   }else setMessage(request.crewName+'\'s request was declined.');
   await Promise.all([load(date,true),loadCrewTripRequests(true)]);window.dispatchEvent(new Event('services-updated'));
  }catch(e){setMessage(e instanceof Error?e.message:'Could not review crew request.');}
  finally{setCrewRequestBusy('');}
 }
